package com.mycompany.rentalmanagement.dao;
import com.mycompany.rentalmanagement.DBConnection;import java.sql.*;import java.util.*;
public class DashboardDAO {public Map<String,Object> stats()throws SQLException{Map<String,Object> m=new LinkedHashMap<>();try(Connection c=DBConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT (SELECT COUNT(*) FROM vehicles WHERE status<>'INACTIVE') vehicles,(SELECT COUNT(*) FROM customers WHERE active=1) customers,(SELECT COUNT(*) FROM rentals WHERE status IN ('BOOKED','ACTIVE')) active_rentals,(SELECT COALESCE(SUM(amount),0) FROM payments WHERE MONTH(paid_at)=MONTH(CURRENT_DATE()) AND YEAR(paid_at)=YEAR(CURRENT_DATE())) monthly_revenue,(SELECT COUNT(*) FROM vehicles WHERE status='AVAILABLE') available_vehicles")){r.next();for(String k:new String[]{"vehicles","customers","active_rentals","monthly_revenue","available_vehicles"})m.put(k,r.getObject(k));}return m;}public List<Map<String,Object>> recent()throws SQLException{List<Map<String,Object>> a=new ArrayList<>();try(Connection c=DBConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT r.id,c.full_name,v.registration_number,r.status,r.start_date FROM rentals r JOIN customers c ON c.id=r.customer_id JOIN vehicles v ON v.id=r.vehicle_id ORDER BY r.id DESC LIMIT 6")){while(r.next()){Map<String,Object> m=new HashMap<>();m.put("id",r.getLong(1));m.put("customer",r.getString(2));m.put("vehicle",r.getString(3));m.put("status",r.getString(4));m.put("date",r.getDate(5));a.add(m);}}return a;}public List<Map<String,Object>> revenue()throws SQLException{List<Map<String,Object>> a=new ArrayList<>();try(Connection c=DBConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT DATE_FORMAT(paid_at,'%Y-%m') month,SUM(amount) total FROM payments WHERE paid_at >= DATE_SUB(CURRENT_DATE(),INTERVAL 6 MONTH) GROUP BY DATE_FORMAT(paid_at,'%Y-%m') ORDER BY month")){while(r.next()){Map<String,Object> m=new HashMap<>();m.put("month",r.getString(1));m.put("total",r.getBigDecimal(2));a.add(m);}}return a;}}
